            padding: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
        }
        .joke-container {
            border: 2px solid #333;
            padding: 20px;
            border-radius: 8px;
            background-color: white;
            width: 80%;
        }
        h1 {
            color: #000;
            margin-bottom: 20px;
        }
        .joke-text {
            color: #000;
            font-size: 2em;
        }
        .button {
            background-color: #4CAF50;
            border: none;
            color: white;
            padding: 15px 32px;
            text-align: center;
            text-decoration: none;
            display: inline-block;
            font-size: 16px;
            margin: 10px 0;
            border-radius: 8px;
            cursor: pointer;
        }
        .button:hover {
            background-color: #45a049;
        }
        .punchline {
            display: none;
        }
